// THE BLUEPRINT (Takes up no physical data memory!)
public class Car {
    // Properties (State)
    String brand;
    String color;
    int maxSpeed;

    // Behaviors (Methods)
    public void startEngine() {
        System.out.println("The " + brand + " engine roars to life.");
    }
}

public class Main {
    public static void main(String[] args) {
        // 1. Declaration: Associates a variable name with an object type.
        Car myCar;

        // 2. Instantiation: The 'new' keyword physically allocates Heap Memory.
        // 3. Initialization: The constructor initializes the new object.
        myCar = new Car(); 

        // Assigning state to this specific object instance
        myCar.brand = "BMW";
        myCar.maxSpeed = 220;
        myCar.startEngine(); // Output: The BMW engine roars to life.
    }
}

class Counter {
    int counterIndex = 0;

    public void increase() { counterIndex++; }
    public void decrease() { counterIndex--; }
    public int getIndex() { return counterIndex; }
}

// THE TRACE EXAM:
Counter c1 = new Counter();
c1.increase(); // Index is now 1
int a = c1.getIndex(); 

c1.increase(); // Index is now 2
int b = c1.getIndex();

if (a > b) { // 1 is NOT greater than 2
    c1.increase();
} else {
    c1.decrease(); // This runs! Index drops back to 1
}
System.out.println(c1.getIndex()); // Final Output: 1

