class Account {
    String owner;
    double balance;

    // Constructor 1: For new customers with zero money
    public Account(String ownerName) {
        owner = ownerName;
        balance = 0.0;
    }

    // Constructor 2: For wealthy customers transferring a starting balance
    public Account(String ownerName, double startingBalance) {
        owner = ownerName;
        balance = startingBalance;
    }
}

// Both work flawlessly because the JVM checks the signature!
Account basic = new Account("John");
Account premium = new Account("Alice", 5000.0);

class Compare {
    // Method 1: Handles Integers
    static int max(int a, int b) {
        if (a > b) return a;
        else return b;
    }

    // Method 2: Handles Strings
    static String max(String a, String b) {
        if (a.compareTo(b) > 0) return a;
        else return b;
    }
}

// The JVM routes the data automatically!
Compare.max(10, 20);            // Triggers Method 1
Compare.max("Sydney", "Perth"); // Triggers Method 2

public class Circle {
    public double x, y, r;

    // Tier 1: The Master Constructor (Provides everything)
    public Circle(double centreX, double centreY, double radius) {
        x = centreX; y = centreY; r = radius;
    }

    // Tier 2: The Partial Constructor (Defaults the center to 0,0)
    public Circle(double radius) {
        x = 0; y = 0; r = radius;
    }

    // Tier 3: The Empty Constructor (Defaults everything)
    public Circle() {
        x = 0; y = 0; r = 1.0;
    }
}

