class Point {
    int x; 
    int y;

    // ✅ THE ARCHITECT'S SOLUTION
    public Point(int x, int y) {
        this.x = x; // Translates to: myObject.x = parameter_x;
        this.y = y;
    }
}

class Player {
    String name;         // Instance: Every player has their own name.
    static int totalPlayers = 0; // Static: Shared by everyone!

    public Player(String name) {
        this.name = name;
        totalPlayers++; // Increases the global class counter!
    }
}

// We can access static variables without even creating an object!
System.out.println(Player.totalPlayers);

public class Circle {
    // STATIC GLOBAL VARIABLE
    private static int numCircles = 0;

    // INSTANCE VARIABLES
    private double x, y, r;

    public Circle(double x, double y, double r) {
        this.x = x;
        this.y = y;
        this.r = r;

        // The magic step: Increment the global counter every time 'new' is called!
        numCircles++; 
    }
}

// Usage:
Circle c1 = new Circle(5, 3, 10); // numCircles becomes 1
Circle c2 = new Circle(10, 12, 20); // numCircles becomes 2

class Circle {
    // 1. Private Data (Hidden from the outside world)
    private double radius;

    // 2. Public Getter (Read-Only Access)
    public double getRadius() {
        return this.radius;
    }

    // 3. Public Setter (Write Access with Bouncer Logic)
    public void setRadius(double r) {
        if (r < 0) {
            System.out.println("Error: Radius cannot be negative!");
        } else {
            this.radius = r;
        }
    }
}
